// Gate A proof harness — NOT part of the tracked importer surface used by
// the real import; runs the REAL write.mjs/orchestrate.mjs functions
// (unmodified) and captures the exact SQL they issue, for execution
// against a disposable Supabase project via `supabase db query`
// (this sandbox has no direct Postgres/pg driver — see Gate A report).
//
// Id-chaining problem: orchestrate.mjs uses one entity's returned id to
// build the next INSERT (e.g. dealId feeds insertHistoricalApplication).
// Since every table here uses `generated by default as identity` and this
// proof runs single-threaded against a database no one else is writing
// to, the NEXT id assigned by Postgres for table T is deterministically
// predictable: read each table's real sequence state once up front
// (last_value/is_called, NOT max(id)+1), then increment a local counter in
// the exact same order statements are issued. This produces ids that are
// byte-identical to what Postgres will actually assign — proven by the
// post-COMMIT reconciliation matrix.
//
// EXISTENCE CHECKS MUST REFLECT THE REAL TARGET. The writer guards every
// insert with a check-then-insert (`select id from client_sessions where
// acuity_appointment_id = $1`, the contact-by-email lookup, ...). An
// earlier version of this shim answered those "no rows" on the assumption
// of a from-scratch database. That assumption died the moment the
// MAIN-derived baseline was loaded, and it made the shim LIE to a writer
// that was behaving correctly: Postgres rejected a duplicate
// acuity_appointment_id, and — far worse — contacts carry NO unique email
// index, so the same lie would have silently created duplicate Contacts
// for every baseline person. So the shim is seeded with the real target
// state and additionally tracks what this run itself inserts, so a later
// check inside the same transaction sees the earlier insert exactly as a
// live connection would.

function sqlLiteral(v) {
  if (v === null || v === undefined) return "NULL";
  if (typeof v === "number") return String(v);
  if (typeof v === "boolean") return v ? "true" : "false";
  if (v instanceof Date) return `'${v.toISOString()}'`;
  const s = String(v).replace(/'/g, "''");
  return `'${s}'`;
}

function interpolate(text, params) {
  return text
    .trim()
    .replace(/\$(\d+)/g, (_, n) => sqlLiteral(params[Number(n) - 1]));
}

const TABLE_BY_INSERT_PATTERN = [
  [/^insert into contacts/i, "contacts"],
  [/^insert into deals/i, "deals"],
  [/^insert into applications/i, "applications"],
  [/^insert into waitlist_entries/i, "waitlist_entries"],
  [/^insert into enrollments/i, "enrollments"],
  [/^insert into deal_stage_events/i, "deal_stage_events"],
  [/^insert into enrollment_status_events/i, "enrollment_status_events"],
  [/^insert into sales_calls/i, "sales_calls"],
  [/^insert into client_sessions/i, "client_sessions"],
  [/^insert into historical_import_records/i, "historical_import_records"],
];

/**
 * Build the live existence indexes from the target database's own rows.
 * @param {object} targetState - dump produced straight from the target
 *   (contacts / salesCallAcuity / clientSessionAcuity / enrollmentsByDeal
 *   / waitlistActive), never hand-written.
 */
function seedIndexes(targetState) {
  const contactsByEmail = new Map();
  for (const c of targetState.contacts ?? []) {
    for (const e of c.email_jsonb ?? []) {
      if (e?.email)
        contactsByEmail.set(String(e.email).trim().toLowerCase(), c);
    }
  }
  return {
    contactsByEmail,
    salesCallByAcuity: new Map(
      (targetState.salesCallAcuity ?? []).map((r) => [String(r.a), r.id]),
    ),
    clientSessionByAcuity: new Map(
      (targetState.clientSessionAcuity ?? []).map((r) => [String(r.a), r.id]),
    ),
    enrollmentByDeal: new Map(
      (targetState.enrollmentsByDeal ?? []).map((r) => [String(r.d), r.id]),
    ),
    waitlistActive: new Map(
      (targetState.waitlistActive ?? []).map((r) => [
        `${r.c}|${r.o}|${r.ch}`,
        r.id,
      ]),
    ),
  };
}

/**
 * @param {Record<string, number>} nextIdByTable - each table's next
 *   identity value, read live from the target's sequences before this pass.
 * @param {object} priorState - { ledger, contactsByEmail, cohortIdByName }
 *   carried over from a real prior pass, for a genuine second-pass
 *   idempotency proof (the SELECT-then-branch logic must see it).
 * @param {object} targetState - the target database's current rows, so
 *   every existence check is answered from reality rather than assumed empty.
 */
export function makeShimClient(
  nextIdByTable,
  priorState = {},
  targetState = {},
) {
  const statements = [];
  const ids = { ...nextIdByTable };
  const idx = seedIndexes(targetState);
  // The provenance ledger IS target state: seed it from the rows actually
  // committed to the target, so a rerun's "already-imported" branch is
  // driven by what the database really holds rather than by a side file
  // that could drift from it.
  const ledger = new Map();
  for (const row of targetState.ledger ?? [])
    ledger.set(`${row.t}:${row.k}`, { entityId: row.e });
  for (const [k, v] of priorState.ledger ?? new Map()) ledger.set(k, v);
  const cohortIdByName = priorState.cohortIdByName ?? new Map();
  // Contacts committed by a prior pass take precedence over the seed (same
  // rows, but the prior-pass map is the one the idempotency proof asserts on).
  for (const [email, row] of priorState.contactsByEmail ?? new Map()) {
    idx.contactsByEmail.set(String(email).trim().toLowerCase(), row);
  }

  // A check-then-insert pair always targets the same key, so remembering
  // the key of the last MISSED check lets the following INSERT register
  // itself in the index without guessing parameter positions.
  let pendingMiss = null;
  let pendingContactEmails = null;

  return {
    statements,
    async query(text, params = []) {
      const trimmed = text.trim();
      const sql = interpolate(trimmed, params);

      const ledgerMatch = trimmed.match(
        /select entity_id from historical_import_records where entity_table = '(\w+)' and source_key = \$1/,
      );
      if (ledgerMatch) {
        const hit = ledger.get(`${ledgerMatch[1]}:${params[0]}`);
        return hit ? { rows: [{ entity_id: hit.entityId }] } : { rows: [] };
      }

      if (
        /^select id, first_name, last_name, stripe_customer_id, email_jsonb\s+from contacts/.test(
          trimmed,
        )
      ) {
        // The writer probes every email the person owns; answer with every
        // DISTINCT contact those emails reach, id-ordered, so its
        // multi-match ambiguity guard sees exactly what a live connection
        // would show it.
        const emails = JSON.parse(params[0]).map((e) =>
          String(e).trim().toLowerCase(),
        );
        const byId = new Map();
        for (const e of emails) {
          const hit = idx.contactsByEmail.get(e);
          if (hit) byId.set(hit.id, hit);
        }
        pendingContactEmails = byId.size === 0 ? emails : null;
        return { rows: [...byId.values()].sort((a, b) => a.id - b.id) };
      }

      if (/select id from cohorts where offer_id/.test(trimmed)) {
        // Real Cohort rows already present in the TARGET database, so the
        // writer's fail-closed name->id lookup resolves exactly as it
        // would over a live connection, never a fabricated id.
        const id = cohortIdByName.get(params[1]);
        return id ? { rows: [{ id }] } : { rows: [] };
      }

      const existenceChecks = [
        [
          /^select id from sales_calls where acuity_appointment_id = \$1/,
          idx.salesCallByAcuity,
          () => String(params[0]),
          "sales_calls",
        ],
        [
          /^select id from client_sessions where acuity_appointment_id = \$1/,
          idx.clientSessionByAcuity,
          () => String(params[0]),
          "client_sessions",
        ],
        [
          /^select id from enrollments where opportunity_id = \$1/,
          idx.enrollmentByDeal,
          () => String(params[0]),
          "enrollments",
        ],
        [
          /^select id from waitlist_entries where contact_id = \$1 and offer_id = \$2/,
          idx.waitlistActive,
          () => `${params[0]}|${params[1]}|${params[2] ?? -1}`,
          "waitlist_entries",
        ],
      ];
      for (const [re, map, keyOf, table] of existenceChecks) {
        if (!re.test(trimmed)) continue;
        const key = keyOf();
        const hit = map.get(key);
        if (hit !== undefined) {
          pendingMiss = null;
          return { rows: [{ id: hit }] };
        }
        pendingMiss = { table, map, key };
        return { rows: [] };
      }

      if (/^select /i.test(trimmed)) {
        statements.push(sql + ";");
        return { rows: [] };
      }

      statements.push(sql + ";");
      if (/returning id$/i.test(trimmed)) {
        const table = TABLE_BY_INSERT_PATTERN.find(([re]) =>
          re.test(trimmed),
        )?.[1];
        if (!table)
          throw new Error(
            `gateA shim: cannot classify table for INSERT: ${trimmed.slice(0, 80)}`,
          );
        const id = ids[table]++;
        // Register this insert so a later check in the SAME transaction
        // sees it, exactly as it would over a live connection.
        if (pendingMiss && pendingMiss.table === table) {
          pendingMiss.map.set(pendingMiss.key, id);
          pendingMiss = null;
        }
        if (table === "contacts" && pendingContactEmails) {
          const row = {
            id,
            first_name: null,
            last_name: null,
            stripe_customer_id: null,
            email_jsonb: pendingContactEmails.map((email) => ({
              email,
              type: "other",
            })),
          };
          for (const e of pendingContactEmails) idx.contactsByEmail.set(e, row);
          pendingContactEmails = null;
        }
        return { rows: [{ id }] };
      }
      return { rows: [] };
    },
  };
}
